<script lang="ts">
  import { SvelteFlow, Background, Controls, MiniMap } from '@xyflow/svelte';
  import '@xyflow/svelte/dist/style.css';
  import RunNode from './RunNode.svelte';
  import GraphFocus from './GraphFocus.svelte';
  import { api, date, elapsed, labels, terminal, type Run, type Event } from './types';
  let {run, refresh, onerror, canOperate}: {run:Run; refresh:()=>Promise<void>; onerror:(text:string)=>void; canOperate:boolean}=$props();
  let selected=$state(''), tab=$state('logs'), view=$state('graph'), log=$state(''), events=$state<Event[]>([]), actionBusy=$state(false), comparison=$state<Run|null>(null);
  let logKey='', eventKey='', eventOlder=$state(false), eventBusy=$state(false);
  let logLoading=$state(false), eventLoading=$state(false), comparisonLoading=$state(false);
  const nodeTypes={step:RunNode};
  let graphWidth=$state(0), graphHeight=$state(0);
  let step=$derived(run.steps.find(s=>s.id===selected)||run.steps.find(s=>['failed','timed_out','interrupted','cancelled'].includes(s.status))||run.steps[0]);
  let activeLogBytes=$derived(step?.log_bytes||0);
  let graph=$derived.by(()=>{
    const levels:Record<string,number>={}; let pending=[...run.steps];
    while(pending.length){let progress=false;for(const s of [...pending]){if(s.needs.every(n=>n in levels)){levels[s.id]=s.needs.length?Math.max(...s.needs.map(n=>levels[n]))+1:0;pending=pending.filter(n=>n.id!==s.id);progress=true;}}if(!progress)break;}
    const lanes:Record<number,number>={};
    return {nodes:run.steps.map((s,i)=>{const x=levels[s.id]||0;const y=lanes[x]||0;lanes[x]=y+1;return{id:s.id,type:'step',position:{x:x*270,y:y*145},data:{label:s.name,status:s.status,duration:elapsed(s.started_at,s.finished_at),index:i},selected:s.id===step?.id}}),edges:run.steps.flatMap(s=>s.needs.map(n=>({id:n+'-'+s.id,source:n,target:s.id,animated:s.status==='running',style:'stroke: #8fa29a; stroke-width: 1.5px;'})))};
  });
  let timelineTotal=$derived(Math.max(1,...run.steps.filter(s=>s.finished_at||s.started_at).map(s=>(Date.parse(s.finished_at||new Date().toISOString())-Date.parse(run.started_at||run.created_at))/1000)));
  $effect(()=>{
    const id=run.id; const sid=step?.id; const bytes=activeLogBytes; const currentTab=tab;let ignore=false;
    if(sid && currentTab==='logs'){
      const key=id+':'+sid;if(logKey!==key){logKey=key;log='';logLoading=true;}
      api<{text:string;next_offset:number}>(`/runs/${id}/logs/${sid}?offset=${Math.max(0,bytes-131072)}`).then(r=>{if(!ignore){log=r.text.replace(/\x1b\[[0-?]*[ -/]*[@-~]/g,'');logLoading=false;}}).catch(e=>{if(!ignore){logLoading=false;onerror(e.message);}});
    }
    if(currentTab==='events'&&sid){
      const key=id+':'+sid;const changed=eventKey!==key;if(changed){eventKey=key;events=[];eventOlder=false;eventLoading=true;}
      api<Event[]>(`/runs/${id}/events?newest=true&step_id=${encodeURIComponent(sid)}`).then(r=>{if(!ignore){if(changed||events.length===0||(r.length===500&&events.length&&!r.some(n=>events.some(e=>e.id===n.id)))){events=[];eventOlder=r.length===500;}events=[...r,...events.filter(e=>!r.some(n=>n.id===e.id))].sort((a,b)=>b.id-a.id);eventLoading=false;}}).catch(e=>{if(!ignore){eventLoading=false;onerror(e.message);}});
    }
    return()=>{ignore=true};
  });
  async function loadOlderEvents(){const key=eventKey, before=events.at(-1)?.id;eventBusy=true;try{const rows=await api<Event[]>(`/runs/${run.id}/events?newest=true&step_id=${encodeURIComponent(step.id)}&before=${before}`);if(key===eventKey&&before===events.at(-1)?.id){events=[...events,...rows];eventOlder=rows.length===500;}}catch(e){onerror(String(e))}finally{eventBusy=false}}
  async function action(kind:string){actionBusy=true;try{const result=await api<Run>(`/runs/${run.id}/${kind}`,'POST',{});if(kind==='retry')location.hash='/runs/'+result.id;else await refresh();}catch(e){onerror(String(e))}finally{actionBusy=false}}
  async function compare(){tab='compare';comparisonLoading=true;try{const runs=await api<Run[]>(`/runs?pipeline=${encodeURIComponent(run.pipeline_id)}&status=succeeded&before=${run.number}&limit=1`);comparison=runs[0]?await api<Run>('/runs/'+runs[0].id):null;}catch(e){onerror(String(e))}finally{comparisonLoading=false}}
</script>
<div class="breadcrumbs"><a href="#/pipelines">Pipelines</a><span>/</span><a href="#/pipelines/{run.pipeline_id}">{run.pipeline_id}</a><span>/</span><span>Lauf #{run.number}</span></div>
<div class="page-heading"><div><div class="eyebrow">AUSFÜHRUNG #{run.number}</div><h1>{run.pipeline_id}</h1><p class="subtle">{date(run.created_at)} · {run.actor} · {run.trigger}</p></div><div class="actions"><span class="badge {run.status}">{labels[run.status]}</span>{#if canOperate}{#if terminal(run.status)}<button class="primary" onclick={()=>action('retry')} disabled={actionBusy}>Erneut ausführen</button>{:else}<button class="danger-button" onclick={()=>action('cancel')} disabled={actionBusy||run.cancel_requested}>{run.cancel_requested?'Abbruch angefordert':'Lauf abbrechen'}</button>{/if}{/if}</div></div>
{#if run.reason}<div class="notice {run.status}" role="status">{run.reason}</div>{/if}
<div class="run-facts"><div><span>Revision</span><code>{run.commit?.slice(0,12)||'Noch nicht aufgelöst'}</code></div><div><span>Dauer</span><strong>{elapsed(run.started_at,run.finished_at)}</strong></div><div><span>Runner</span><strong>{run.runner||'Wartet auf Kapazität'}</strong></div><div><span>Fortschritt</span><strong>{run.steps.filter(s=>terminal(s.status)).length} / {run.steps.length} Schritte</strong></div></div>
{#if run.parent_id||run.retry_of}<p class="related">{#if run.parent_id}<a href="#/runs/{run.parent_id}">↗ Übergeordneter Lauf</a>{/if}{#if run.retry_of}<a href="#/runs/{run.retry_of}">↗ Ursprünglicher Versuch</a>{/if}</p>{/if}
<section class="panel pipeline-panel" aria-label="Pipeline-Visualisierung">
  <div class="panel-heading"><h2>Pipeline-Verlauf</h2><div class="segmented"><button class:active={view==='graph'} onclick={()=>view='graph'}>Graph</button><button class:active={view==='timeline'} onclick={()=>view='timeline'}>Zeitachse</button></div></div>
  {#if view==='graph'}<div class="graph" bind:clientWidth={graphWidth} bind:clientHeight={graphHeight}><SvelteFlow nodes={graph.nodes} edges={graph.edges} {nodeTypes} fitView={graphWidth>1050&&run.steps.length<=5} initialViewport={{x:24,y:28,zoom:0.95}} minZoom={0.2} maxZoom={1.5} nodesDraggable={false} nodesConnectable={false} onnodeclick={({node})=>selected=node.id}><Background gap={20} patternColor="#dce4df"/><Controls showLock={false}/><GraphFocus nodeId={step?.id||''} runId={run.id} width={graphWidth} height={graphHeight}/>{#if graphWidth<1050||run.steps.length>5}<MiniMap pannable zoomable width={130} height={70} ariaLabel="Gesamtübersicht der Pipeline"/>{/if}</SvelteFlow></div><p class="graph-help">Schritt anklicken für Details.</p>
  {:else}<div class="timeline"><div class="timeline-axis"><span>Start</span><span>{Math.ceil(timelineTotal)} Sekunden</span></div>{#each run.steps as s}<button class="timeline-row" aria-label={`${s.name} · ${labels[s.status]} · ${elapsed(s.started_at,s.finished_at)}`} title={labels[s.status]} onclick={()=>selected=s.id}><span>{s.name}</span><div class="track"><div class="bar {s.status}" style:left="{s.started_at?Math.max(0,(Date.parse(s.started_at)-Date.parse(run.started_at||run.created_at))/1000/timelineTotal*100):0}%" style:width="{s.started_at?Math.max(1,((Date.parse(s.finished_at||new Date().toISOString())-Date.parse(s.started_at))/1000)/timelineTotal*100):0}%"></div></div><span>{elapsed(s.started_at,s.finished_at)}</span></button>{/each}</div>{/if}
</section>
<div class="detail-layout"><aside class="step-list" aria-label="Schritte">{#each run.steps as s,i}<button class:chosen={s.id===step?.id} onclick={()=>selected=s.id}><span class="step-order">{String(i+1).padStart(2,'0')}</span><div><strong>{s.name}</strong><small><span class="status-dot {s.status}"></span>{labels[s.status]}</small></div><span class="step-time">{elapsed(s.started_at,s.finished_at)}</span></button>{/each}</aside>
<section class="panel step-detail"><div class="panel-heading"><div><div class="eyebrow">SCHRITTDETAILS</div><h2>{step?.name}</h2></div><span class="badge {step?.status}">{labels[step?.status]}</span></div>
<div class="tabs" aria-label="Detailansicht">{#each [['logs','Konsole'],['outputs','Ergebnisse'],['artifacts','Artefakte'],['events','Ereignisse']] as [key,label]}<button class:active={tab===key} onclick={()=>tab=key}>{label}</button>{/each}<button class:active={tab==='compare'} onclick={compare} disabled={comparisonLoading}>Vergleichen</button></div>
{#if step?.reason}<div class="step-reason">{step.reason}</div>{/if}
{#if tab==='logs'}<div class="console-meta"><span>Ausgabe · {step?.log_bytes||0} Bytes · <a href="/api/runs/{run.id}/logs/{step?.id}/download" download>Vollständiges Log</a></span><span>{step?.exit_code===null?'':`Exitcode ${step?.exit_code}`}</span></div><!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable output needs keyboard access.) --><pre class="console" tabindex="0" role="region" aria-label="Konsolenausgabe" aria-busy={logLoading}>{logLoading?'Ausgabe wird geladen …':log||'Keine Ausgabe.'}</pre>
{:else if tab==='outputs'}<div class="detail-content"><h3>Strukturierte Ergebnisse</h3><!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable output needs keyboard access.) --><pre class="json" tabindex="0" role="region" aria-label="Strukturierte Daten">{JSON.stringify(step?.outputs||{},null,2)}</pre><h3>Laufparameter</h3><!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable output needs keyboard access.) --><pre class="json" tabindex="0" role="region" aria-label="Strukturierte Daten">{JSON.stringify(run.parameters,null,2)}</pre><h3>Ausführungsidentität</h3><code class="wrap">{run.image_digest||'Runner-Image noch nicht aufgelöst'}</code></div>
{:else if tab==='artifacts'}<div class="detail-content">{#each run.artifacts.filter(a=>a.step_id===step?.id) as a}<a class="artifact-row" href="/api/artifacts/{a.id}" download><span>↓</span><div><strong>{a.name}</strong><small>{a.size.toLocaleString('de-DE')} Bytes · SHA-256 {a.sha256.slice(0,16)}…</small></div></a>{:else}<div class="empty-state"><strong>Keine Artefakte für diesen Schritt</strong></div>{/each}</div>
{:else if tab==='events'}<div class="detail-content event-list" aria-busy={eventLoading}>{#if eventLoading}<p role="status">Ereignisse werden geladen …</p>{:else}{#each events as e}<div><time>{date(e.created_at)}</time><strong>{e.kind}</strong><span>{String(e.data.reason||'')}</span></div>{:else}<p>Keine Ereignisse vorhanden.</p>{/each}{#if eventOlder}<button onclick={loadOlderEvents} disabled={eventBusy}>{eventBusy?'Wird geladen …':'Ältere Ereignisse laden'}</button>{/if}{/if}</div>
{:else}<div class="detail-content">{#if comparisonLoading}<p role="status">Vergleich wird geladen …</p>{:else if comparison}<h3>Vergleich mit erfolgreichem Lauf <a href="#/runs/{comparison.id}">#{comparison.number}</a></h3><dl class="comparison"><dt>Revision vorher</dt><dd><code>{comparison.commit?.slice(0,12)||'—'}</code></dd><dt>Revision jetzt</dt><dd><code>{run.commit?.slice(0,12)||'—'}</code></dd><dt>Dauer vorher</dt><dd>{elapsed(comparison.started_at,comparison.finished_at)}</dd><dt>Dauer jetzt</dt><dd>{elapsed(run.started_at,run.finished_at)}</dd></dl><h3>Parameteränderungen</h3><!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable output needs keyboard access.) --><pre class="json" tabindex="0" role="region" aria-label="Strukturierte Daten">{JSON.stringify(Object.fromEntries(Object.keys({...comparison.parameters,...run.parameters}).filter(k=>JSON.stringify(comparison!.parameters[k])!==JSON.stringify(run.parameters[k])).map(k=>[k,{vorher:comparison!.parameters[k],jetzt:run.parameters[k]}])),null,2)}</pre>{:else}<div class="empty-state"><strong>Noch kein erfolgreicher Vergleichslauf</strong></div>{/if}</div>{/if}
</section></div>
{#if run.children.length}<section class="panel child-runs"><div class="panel-heading"><h2>Unterpipelines</h2></div>{#each run.children as child}<a class="child-row" href="#/runs/{child.id}"><strong>{child.pipeline_id}</strong><span>#{child.number}</span><span class="badge {child.status}">{labels[child.status]}</span></a>{/each}</section>{/if}
